@dataclass
class Batch:
    table: str
    rows: list

def __add__(self, other):
    if not isinstance(other, Money):
        return NotImplemented
    return Money(self.cents + other.cents)

class Trip:
    def __init__(self, fare, km):
        self.fare, self.km = fare, km

    @property
    def fare_per_km(self):
        return round(self.fare / self.km, 2) if self.km else 0.0

t = Trip(100.0, 8.0)
t.fare_per_km   # 12.5
